const app=document.getElementById('app');
const $=(s)=>document.querySelector(s);
let state;
const cards=[
{id:'tackle',name:'Tackle',cost:1,art:'⚡',cls:'',desc:'Deal 6 damage',kind:'damage',value:6},
{id:'growl',name:'Growl',cost:1,art:'🗯️',cls:'green',desc:'Gain 5 Guard',kind:'block',value:5},
{id:'quick',name:'Quick Attack',cost:1,art:'💨',cls:'yellow',desc:'Deal 4 · Draw 1',kind:'quick',value:4},
{id:'bite',name:'Bite',cost:2,art:'🦷',cls:'red',desc:'Deal 10 damage',kind:'damage',value:10},
{id:'rest',name:'Rest',cost:1,art:'🌿',cls:'green',desc:'Heal 5 HP',kind:'heal',value:5}
];
const enemies=[['Speckit',55,9],['Thornub',68,11],['Emberling',62,13],['Wild Pidgeon',78,14]];
function copy(a){return JSON.parse(JSON.stringify(a))}
function start(){state={floor:1,player:{hp:80,max:80,guard:0,energy:3,deck:copy([cards[0],cards[0],cards[1],cards[1],cards[2],cards[3],cards[4],cards[0],cards[2],cards[1]]),hand:[],draw:[],discard:[]},enemy:null,wild:null};nextEnemy(true)}
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function nextEnemy(init=false){let e=enemies[Math.min(state.floor-1,enemies.length-1)];let extra=Math.floor((state.floor-1)*4);state.enemy={name:e[0],hp:e[1]+extra,max:e[1]+extra,damage:e[2]+Math.floor(state.floor/2),intent:'attack'};state.player.guard=0;state.player.energy=3;state.player.draw=shuffle([...state.player.deck]);state.player.hand=[];state.player.discard=[];drawCards(init?5:5);render()}
function drawCards(n){while(n--&&state.player.draw.length)state.player.hand.push(state.player.draw.shift());render()}
function cardHTML(c,i){return `<button class="card ${c.cls}" data-card="${i}"><div class="card-cost">${c.cost}</div><div class="card-title">${c.name}</div><div class="card-art">${c.art}</div><div class="card-desc">${c.desc}</div></button>`}
function render(){const p=state.player,e=state.enemy;app.innerHTML=`<div class="game"><header><div class="brand"><div class="pokeball"></div> POKESPIRE</div><div class="stats"><div class="stat">FLOOR<b>${state.floor}/5</b></div><div class="stat">HP<b>${p.hp}/${p.max}</b></div></div></header><section class="arena"><div class="sky"></div><div class="path"></div><div class="log">${state.log||'Choose a move!'}</div><div class="heroes"><div class="fighter hero-sprite"><div class="sprite"><div class="ears"></div><div class="tail"></div><div class="body"></div><div class="belly"></div><div class="eye l"></div><div class="eye r"></div></div><div class="hpbar"><i style="width:${p.hp/p.max*100}%"></i></div></div></div><div class="enemy-zone"><div class="enemy-name">${e.name}</div><div class="fighter enemy" id="enemy"><div class="sprite"><div class="flame"></div><div class="body"></div><div class="eye l"></div><div class="eye r"></div></div><div class="intent">⚔ ${e.damage}</div><div class="hpbar"><i style="width:${e.hp/e.max*100}%"></i></div></div></div></section><section class="hand"><div><div class="energy">${[0,1,2].map(i=>`<div class="orb ${i>=p.energy?'used':''}">${i< p.energy?'★':''}</div>`).join('')}</div></div><div><div class="cards">${p.hand.map(cardHTML).join('')}</div></div><div><button class="endturn" id="endturn">END TURN</button><div class="deckcount">Draw ${p.draw.length} · Discard ${p.discard.length}</div></div></section></div>`;bind()}
function bind(){document.queryAll='';document.querySelectorAll('[data-card]').forEach(btn=>btn.onclick=()=>playCard(+btn.dataset.card));$('#endturn').onclick=endTurn}
function toast(t){let el=document.createElement('div');el.className='toast';el.textContent=t;app.append(el);setTimeout(()=>el.remove(),1300)}
function playCard(i){let c=state.player.hand[i];if(!c)return;if(c.cost>state.player.energy){toast('Not enough energy!');return}state.player.energy-=c.cost;state.player.hand.splice(i,1);state.player.discard.push(c);let e=state.enemy,p=state.player;if(c.kind==='damage'||c.kind==='quick'||c.kind==='bite'){let dmg=c.value;e.hp=Math.max(0,e.hp-dmg);state.log=`Pikachu used ${c.name}! −${dmg} HP`;let h=document.querySelector('.hero');h?.classList.add('attack')}if(c.kind==='block'){p.guard+=c.value;state.log=`Pikachu gained ${c.value} Guard!`}if(c.kind==='heal'){p.hp=Math.min(p.max,p.hp+c.value);state.log=`Pikachu restored ${c.value} HP!`}if(c.kind==='quick')drawCards(1);if(e.hp<=0){render();setTimeout(win,350);return}render()}
function enemyAttack(){let e=state.enemy,p=state.player;let damage=Math.max(0,e.damage-p.guard);p.guard=Math.max(0,p.guard-e.damage);p.hp=Math.max(0,p.hp-damage);state.log=`${e.name} attacked for ${damage} damage!`;render();if(p.hp<=0)setTimeout(loss,300)}
function endTurn(){state.player.discard.push(...state.player.hand);state.player.hand=[];enemyAttack();setTimeout(()=>{if(state.player.hp>0){state.player.energy=3;state.player.guard=0;if(state.player.draw.length<5){state.player.draw=shuffle([...state.player.deck]);state.player.discard=[]}drawCards(5)}},350)}
function win(){if(state.floor>=5){victory();return}state.wild={name:['Oddish','Eevee','Charmander','Squirtle'][state.floor-1],art:['🌱','🦊','🔥','🐢'][state.floor-1],chance:70-state.floor*5};modal(`Wild <b>${state.wild.name}</b> appeared!`,`<div class="choice" id="catch"><div style="font-size:70px">${state.wild.art}</div><h3>Throw Poké Ball</h3><div class="catchrate"><i style="width:${state.wild.chance}%"></i></div><small>${state.wild.chance}% catch chance</small></div><div class="choice" id="leave"><div style="font-size:70px">🏃</div><h3>Keep Moving</h3><small>Continue with your team</small></div>`,'catch')}
function modal(title,html,kind){let m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="panel"><h1>${title}</h1><div class="choices">${html}</div></div>`;app.append(m);if(kind==='catch'){m.querySelector('#catch').onclick=()=>{m.remove();let caught=Math.random()*100<state.wild.chance;if(caught){let newCard={...cards[state.floor%cards.length],id:'caught'+Date.now(),name:['Giga Drain','Hasty Hound','Blaze Kick','Shell Toss'][state.floor-1]};state.player.deck.push(newCard);toast(`${state.wild.name} joined your deck!`)}else toast(`The wild ${state.wild.name} broke free!`);nextFloor()};m.querySelector('#leave').onclick=()=>{m.remove();nextFloor()}}}
function nextFloor(){state.floor++;if(state.floor<=4){state.player.max+=5;state.player.hp=Math.min(state.player.max,state.player.hp+15);state.enemy=null;toast('A moment to rest...');setTimeout(()=>nextEnemy(),600)}}
function loss(){modal('The Trail Ends','<div class="choice" id="retry"><div style="font-size:70px">🔄</div><h3>Try Again</h3></div>','none');document.querySelector('#retry').onclick=()=>{document.querySelector('.modal').remove();start()}}
function victory(){modal('Champion of the Wilds','<div class="choice" id="retry"><div style="font-size:70px">🏆</div><h3>Play Again</h3></div>','none');document.querySelector('#retry').onclick=()=>{document.querySelector('.modal').remove();start()}}
start();

